import { decodeInlineNotes } from "./solution";

function assertJson(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}

assertJson(decodeInlineNotes(""), [], "empty input");
assertJson(
  decodeInlineNotes("Start {{note:remember}} then {{warning:careful}} and {{key:Ctrl+K}}."),
  [
    { type: "text", text: "Start " },
    { type: "note", text: "remember" },
    { type: "text", text: " then " },
    { type: "warning", text: "careful" },
    { type: "text", text: " and " },
    { type: "key", text: "Ctrl+K" },
    { type: "text", text: "." },
  ],
  "recognized markers and source order",
);
assertJson(
  decodeInlineNotes("{{route:Settings|/account/settings}}"),
  [{ type: "route", text: "Settings", target: "/account/settings" }],
  "route decoding",
);
assertJson(
  decodeInlineNotes("{{note:}}{{warning:}}{{key:}}{{route:|}}{{route:left|}}"),
  [
    { type: "note", text: "" },
    { type: "warning", text: "" },
    { type: "key", text: "" },
    { type: "route", text: "", target: "" },
    { type: "route", text: "left", target: "" },
  ],
  "empty payloads and route fields",
);
assertJson(
  decodeInlineNotes("A\\*B {{note:x\\|y}} {{route:left\\|side|target\\|part}} tail\\"),
  [
    { type: "text", text: "A*B " },
    { type: "note", text: "x|y" },
    { type: "text", text: " " },
    { type: "route", text: "left|side", target: "target|part" },
    { type: "text", text: " tail\\" },
  ],
  "escaping inside and outside markers",
);
assertJson(
  decodeInlineNotes("x{{other:value}}y{{route:no-separator}}z{{note:unfinished"),
  [{ type: "text", text: "x{{other:value}}y{{route:no-separator}}z{{note:unfinished" }],
  "unknown, malformed, and incomplete markers remain coalesced text",
);
assertJson(decodeInlineNotes("{{note:first}}"), [{ type: "note", text: "first" }], "first call stability");
assertJson(decodeInlineNotes("plain"), [{ type: "text", text: "plain" }], "no retained state between calls");

